sysauto_script.script:
(function() {
    try {
        var profileName = "Cisco Secure Access Auth Profile";

        // 🔹 Fetch clientKey + clientSecret from sys_auth_profile_basic
        var bap = new GlideRecord("sys_auth_profile_basic");
        bap.addQuery("name", profileName);
        bap.query();
        if (!bap.next()) {
            gs.error("No Basic Auth Profile found with name: " + profileName);
            return;
        }

        var clientKey = bap.username.toString();
        var clientSecret = bap.password.toString();
        if (!clientKey || !clientSecret) {
            gs.error("Missing clientKey or clientSecret in Auth Profile");
            return;
        }

        // 🔹 Prepare Authorization header
        var authString = clientKey + ":" + clientSecret;
        var encodedAuth = GlideStringUtil.base64Encode(authString);

        // 🔹 Call Cisco API
        var r = new sn_ws.RESTMessageV2();
        r.setEndpoint("https://api.sse.cisco.com/auth/v2/token");
        r.setHttpMethod("GET");
        r.setRequestHeader("Authorization", "Basic " + encodedAuth);

        var resp = r.execute();
        var status = resp.getStatusCode();
        var body = resp.getBody();

        gs.info("Cisco CSA Token Refresh - Status: " + status);
        gs.info("Cisco CSA Token Refresh - Body: " + body);

        if (status != 200) {
            gs.error("Token refresh failed. Status: " + status + " Body: " + body);
            return;
        }

        // 🔹 Parse response
        var parsed;
        try {
            parsed = JSON.parse(body);
        } catch (e) {
            gs.error("Failed to parse token response: " + e.message);
            return;
        }

        if (!parsed.access_token) {
            gs.error("No access_token found in token response");
            return;
        }

        var expires = parsed.expires_in;
        var expiry = new GlideDateTime();
        expiry.addSeconds(expires);

        // 🔹 Clear old tokens
        var oldTokens = new GlideRecord("u_cisco_secure_access_token");
        oldTokens.query();
        while (oldTokens.next()) {
            oldTokens.deleteRecord();
        }

        // 🔹 Store new token
        var gr = new GlideRecord("u_cisco_secure_access_token");
        gr.initialize();
        gr.u_access_token = parsed.access_token;
        gr.u_token_type = parsed.token_type;
        gr.u_expiry_date_time = expiry;
        gr.u_expires_in = expires;
        gr.u_status = "Active";
        gr.u_created_on = new GlideDateTime();
        var tokenId = gr.insert();

        gs.info("Token refreshed successfully. New sys_id: " + tokenId);

    } catch (ex) {
        gs.error("Error refreshing token: " + ex.message);
    }
})();
